#!/usr/bin/env node
// Points the editor at a site. Reads editor.config.json and writes:
//   - assets/js/site-config.js  (what the editor loads)
//   - the Content-Security-Policy in index.html and preview.html, which only
//     allows scripts from this editor and the configured site
//   - CNAME (the editor's own domain on GitHub Pages)
//
//   node scripts/configure.mjs           apply editor.config.json
//   node scripts/configure.mjs --check   exit 1 if generated files are out of sync
//   node scripts/configure.mjs --site URL [--out DIR]   (used by tests)
import { readFile, writeFile, rm, access } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const args = process.argv.slice(2);
const opt = (name) => { const i = args.indexOf(name); return i >= 0 ? args[i + 1] : undefined; };
const outDir = resolve(opt('--out') || root);
const check = args.includes('--check');

const config = JSON.parse(await readFile(join(root, 'editor.config.json'), 'utf8'));
if (opt('--site')) config.siteUrl = opt('--site');
const site = new URL(config.siteUrl);
if (!/^https?:$/.test(site.protocol)) throw new Error('siteUrl must be http(s)');
if (site.protocol === 'http:' && !['localhost', '127.0.0.1'].includes(site.hostname)) throw new Error('siteUrl must use https');
const origin = site.origin;
const { owner, name, branch = 'main' } = config.repo || {};
if (!/^[\w.-]+$/.test(owner || '') || !/^[\w.-]+$/.test(name || '') || !/^[\w./-]+$/.test(branch)) throw new Error('repo.owner, repo.name and repo.branch are required');

// Videos, maps and the booking calendars the site can show (BOOKING_ORIGINS in
// the site's blocks.js; the browser tests check the two lists match).
export const FRAME_ORIGINS = ['https://www.youtube-nocookie.com', 'https://player.vimeo.com', 'https://www.google.com',
  'https://calendly.com', 'https://cal.com', 'https://app.cal.com', 'https://outlook.office365.com', 'https://outlook.office.com',
  'https://calendar.google.com', 'https://meetings.hubspot.com', 'https://app.acuityscheduling.com'];

export function csp(siteOrigin, { preview = false } = {}) {
  return [
    "default-src 'self'",
    `script-src 'self' ${siteOrigin}`,
    `style-src 'self' 'unsafe-inline' ${siteOrigin} https://fonts.googleapis.com`,
    "font-src 'self' https://fonts.gstatic.com",
    `img-src 'self' data: blob: https: ${siteOrigin}`,
    `connect-src 'self' https://api.github.com ${siteOrigin}`,
    preview ? `frame-src ${FRAME_ORIGINS.join(' ')}` : "frame-src 'self'",
    `base-uri 'self' ${siteOrigin}`,
    "object-src 'none'",
    "form-action 'self'",
  ].join('; ');
}

const files = new Map();
files.set('assets/js/site-config.js', `// Generated by scripts/configure.mjs from editor.config.json. Do not edit by hand.
export const CONFIG = ${JSON.stringify({ siteUrl: origin, repo: { owner, name, branch } }, null, 2)};
`);
for (const [file, preview] of [['index.html', false], ['preview.html', true]]) {
  const html = await readFile(join(root, file), 'utf8');
  let next = html.replace(/(<meta http-equiv="Content-Security-Policy" content=")[^"]*(")/, `$1${csp(origin, { preview })}$2`);
  if (next === html && !html.includes(csp(origin, { preview }))) throw new Error(`${file} has no CSP meta tag`);
  if (preview) {
    // The site's stylesheet must load before the draft's theme variables, or its defaults win.
    if (!/<link id="site-css"[^>]*>\s*<style id="theme-vars">/.test(next)) throw new Error('preview.html needs <link id="site-css"> right before <style id="theme-vars">');
    next = next.replace(/(<link id="site-css" rel="stylesheet" href=")[^"]*(")/, `$1${origin}/assets/css/site.css$2`);
  }
  files.set(file, next);
}
const wantCname = config.editorDomain && !opt('--site');
if (wantCname) files.set('CNAME', `${config.editorDomain}\n`);
// Without an editorDomain the editor is served from GitHub's own address, so an old CNAME must go.
const staleCname = !wantCname && !opt('--site') && await access(join(root, 'CNAME')).then(() => true, () => false);

if (check) {
  const stale = [];
  for (const [file, content] of files) if ((await readFile(join(root, file), 'utf8').catch(() => '')) !== content) stale.push(file);
  if (staleCname) stale.push('CNAME (no editorDomain set)');
  if (stale.length) { console.error(`Out of sync with editor.config.json: ${stale.join(', ')}\nRun: node scripts/configure.mjs`); process.exit(1); }
  console.log('Configuration is in sync.');
} else {
  for (const [file, content] of files) await writeFile(join(outDir, file), content);
  if (staleCname) await rm(join(root, 'CNAME'), { force: true });
  console.log(`Editor configured for ${origin} (${owner}/${name}@${branch})${outDir !== root ? ` in ${outDir}` : ''}.`);
}
